# Initially generated by GitHub Copilot.
from __future__ import annotations

from pathlib import Path
import shutil
import subprocess

from repo_util.common import format_command, run_cmd, write_json, write_text
from repo_util.repo_selection import RepoInfo


def _select_black_command(repo_dir: Path, target: str) -> list[str] | None:
    black_exe = repo_dir / ".venv" / "Scripts" / "black.exe"
    venv_python = repo_dir / ".venv" / "Scripts" / "python.exe"

    if black_exe.is_file():
        return [str(black_exe), target]
    if venv_python.is_file():
        return [str(venv_python), "-m", "black", target]
    path_black = shutil.which("black")
    if path_black is not None:
        return [path_black, target]
    return None


def _to_lines(stdout: str | None, stderr: str | None) -> list[str]:
    merged = ""
    if stdout:
        merged += stdout
    if stderr:
        merged += stderr
    return [line for line in merged.splitlines()]


def _render_txt_report(results: list[dict]) -> str:
    lines: list[str] = []
    for item in results:
        black = item["black"]
        lines.append(f"=== {item['repo']} ===")
        lines.append(f"repo_path: {item['repo_path']}")
        lines.append(f"today_commit: {item['today_commit']}")
        if black["attempted"]:
            lines.append(
                "black: "
                f"attempted={black['attempted']} "
                f"success={black['success']} "
                f"exit_code={black['exit_code']}"
            )
            lines.append(f"black_command: {black['command']}")
            for output_line in black["output"]:
                lines.append(f"black_out: {output_line}")
        else:
            lines.append(
                "black: " f"attempted={black['attempted']} " f"note={black['note']}"
            )
        lines.append("")
    return "\n".join(lines) + "\n"


def run_black_across_repos(
    repo_infos: list[RepoInfo],
    *,
    black_target: str,
    black_timeout_sec: float | None,
    report_json: Path | None,
    report_txt: Path | None,
) -> list[dict]:
    results: list[dict] = []

    for repo_info in repo_infos:
        command = _select_black_command(repo_info.path, black_target)
        black_result = {
            "attempted": False,
            "success": False,
            "exit_code": None,
            "command": "",
            "output": [],
            "note": "",
        }

        if command is None:
            black_result["note"] = (
                "Skipped: black command unavailable (.venv/Scripts/black.exe and .venv/Scripts/python.exe are missing)"
            )
        else:
            black_result["attempted"] = True
            black_result["command"] = format_command(command)
            try:
                result = run_cmd(
                    command, cwd=repo_info.path, timeout_sec=black_timeout_sec
                )
                black_result["exit_code"] = result.returncode
                black_result["success"] = result.returncode == 0
                black_result["output"] = _to_lines(result.stdout, result.stderr)
            except subprocess.TimeoutExpired as exc:
                black_result["success"] = False
                black_result["note"] = (
                    f"Timed out after {black_timeout_sec} seconds while running black"
                )
                stdout = exc.stdout if isinstance(exc.stdout, str) else ""
                stderr = exc.stderr if isinstance(exc.stderr, str) else ""
                black_result["output"] = _to_lines(stdout, stderr)

        results.append(
            {
                "repo": repo_info.name,
                "repo_path": str(repo_info.path),
                "today_commit": repo_info.head_commit,
                "today_commit_source": "head-committer-date",
                "black": black_result,
            }
        )

    if report_json is not None:
        write_json(report_json, results)
    if report_txt is not None:
        write_text(report_txt, _render_txt_report(results))

    print(f"REPO_COUNT={len(results)}")
    for result in results:
        black_result = result["black"]
        print(
            "REPO={0}; BLACK_ATTEMPTED={1}; BLACK_OK={2}".format(
                result["repo"],
                black_result["attempted"],
                black_result["success"],
            )
        )

    return results
